/** Fast lookup by tool name. */
const SPEC_BY_NAME = new Map<string, ExpandedToolSpec>(
  EXPANDED_TOOL_SPECS.map((spec) => [spec.name, spec]),
);

export function expandedToolSpec(name: string): ExpandedToolSpec | undefined {
  return SPEC_BY_NAME.get(name);
}

/** One argument's Zod type. Always `.optional()` — see the file header for why. */
function argToZod(arg: ExpandedArgSpec): z.ZodTypeAny {
  let base: z.ZodTypeAny;
  switch (arg.type) {
    case 'number':
      base = z.number();
      break;
    case 'boolean':
      base = z.boolean();
      break;
    case 'enum':
      base = arg.enumValues && arg.enumValues.length
        ? z.enum(arg.enumValues as [string, ...string[]])
        : z.string();
      break;
    case 'array':
      // Every array argument in the catalogue is a list of ids/keys.
      base = z.array(z.union([z.string(), z.number()]));
      break;
    case 'object':
      // A property value whose type depends on the property (number, string,
      // colour array, channel-type object). Left permissive on purpose.
      base = z.any();
      break;
    case 'string':
    default:
      // A string whose documented default is numeric also accepts a number
      // (e.g. a pixel-aspect-ratio of 1.0 or "16:9").
      base = typeof arg.default === 'number'
        ? z.union([z.string(), z.number()])
        : z.string();
      break;
  }
  const prefix = arg.required ? '(required) ' : '';
  return base.describe(prefix + arg.description).optional();
}

/**
 * Build the Zod input schema for an expanded tool from its spec. Every field is
 * optional (requiredness is documented and enforced in the handler), so the
 * schema never rejects a caller that used an alternate argument spelling.
 */
export function buildExpandedInputSchema(spec: ExpandedToolSpec): z.ZodTypeAny {
  const shape: Record<string, z.ZodTypeAny> = {};
  for (const arg of spec.args) shape[arg.name] = argToZod(arg);
  return z.object(shape);
}
